"""Lecture 30 vignette pool B -- Arrhythmias II: bundle branch blocks,
premature ventricular contractions, sudden cardiac death and the implantable
defibrillator.

KEYS ARE WRITTEN SHORT ON PURPOSE -- detail lives in the explanation.

Patient vignettes with a varied lead-in. A new left bundle branch block is
keyed only as a sign of pathology to work up (never as a ST-elevation
equivalent; s27 against the changed guideline). Her one "highlight today" --
premature ventricular contractions come mainly from hypoxemia and electrolyte
imbalance -- is in more than one stem. Scope caps live in cms_e5l30_scope.py.
"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from _cmse3_q import Q
from cms_e5l30_scope import *


def S(topic, io, q, opts, cite, slot):
    d = Q(topic, io, q, opts, cite); d["slot"] = slot; return d


def V(topic, io, q, opts, cite, slot, lead):
    d = S(topic, io, q, opts, cite, slot); d["lead"] = lead; return d


LBB = "Left bundle branch block"
RBB = "Right bundle branch block"
